test("deletion order handles shuffled graphs, shared dependencies, and missing parents", () => {
  const resources = [
    res("volume", "volume", "feat-a"),
    res("dns", "dns_record", "feat-a", ["lb"]),
    res("snapshot", "snapshot", "feat-a", ["volume"]),
    res("instance", "instance", "feat-a", ["volume", "subnet"]),
    res("network", "network", "feat-a"),
    res("lb", "load_balancer", "feat-a", ["subnet"]),
    res("subnet", "subnet", "feat-a", ["network", "missing"]),
  ];
  const before = structuredClone(resources);
  const order = buildPlan(resources, "feat-a").steps.map((r) => r.id);
  assert.equal(new Set(order).size, resources.length);
  for (const r of resources) {
    for (const dependency of r.depends_on) {
      if (order.includes(dependency)) assert.ok(order.indexOf(r.id) < order.indexOf(dependency));
    }
  }
  assert.deepEqual(resources, before);
});

